
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lc_wpbesol_whs_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lc_wpbesol_whs", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.983979247944505e+00, -3.900354296764852e+00, -3.783207649628805e+00, -3.621000432963477e+00, -3.400128415816139e+00, -3.106521759171293e+00, -2.729467091972211e+00, -2.268629546807320e+00, -1.744006306216484e+00, -1.203375399643056e+00, -7.142591466404954e-01, -4.503135223171968e-01, -3.741778048039242e-01, -2.642815278210371e-01, -1.353344369536743e-01, -3.936468160373564e-02, -4.474975101684059e-03, -1.322013659658083e-04, -1.201677045978292e-06, -1.656006524118462e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


